-- Generated by tools/build_mysql_schema.py. Target: MySQL 8.0.16+ (CHECK enforcement).
-- No CREATE DATABASE, DROP, or credentials. Review before applying to an existing service.
CREATE TABLE IF NOT EXISTS schema_migration (
  version BIGINT PRIMARY KEY, applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS registry_bundle (
  id VARCHAR(64) PRIMARY KEY, version VARCHAR(255) NOT NULL, sha256 CHAR(64) NOT NULL UNIQUE,
  reference_markdown LONGTEXT NOT NULL, snapshot_json JSON NOT NULL CHECK(json_valid(snapshot_json)),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS tag_definition (
  bundle_id VARCHAR(64) NOT NULL, code VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL, stage VARCHAR(64) NOT NULL, definition_json JSON NOT NULL CHECK(json_valid(definition_json)),
  PRIMARY KEY(bundle_id, code),
  FOREIGN KEY(bundle_id) REFERENCES registry_bundle(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS label_definition (
  bundle_id VARCHAR(64) NOT NULL, code VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL, value_type VARCHAR(64) NOT NULL, comparison_scope VARCHAR(64) NOT NULL,
  definition_json JSON NOT NULL CHECK(json_valid(definition_json)), PRIMARY KEY(bundle_id, code),
  FOREIGN KEY(bundle_id) REFERENCES registry_bundle(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS tag_label_binding (
  bundle_id VARCHAR(64) NOT NULL, tag_code VARCHAR(64) NOT NULL, label_code VARCHAR(64) NOT NULL,
  extraction_enabled BIGINT NOT NULL DEFAULT 1 CHECK(extraction_enabled IN (0,1)),
  PRIMARY KEY(bundle_id, tag_code, label_code),
  FOREIGN KEY(bundle_id, tag_code) REFERENCES tag_definition(bundle_id, code),
  FOREIGN KEY(bundle_id, label_code) REFERENCES label_definition(bundle_id, code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS rule_definition (
  bundle_id VARCHAR(64) NOT NULL, code VARCHAR(64) NOT NULL,
  kind VARCHAR(64) NOT NULL CHECK(kind IN ('presence','identity','consistency','chronology','duplicate','coverage','content')),
  name VARCHAR(255) NOT NULL, definition_json JSON NOT NULL CHECK(json_valid(definition_json)),
  PRIMARY KEY(bundle_id, code),
  FOREIGN KEY(bundle_id) REFERENCES registry_bundle(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS project (
  id VARCHAR(64) PRIMARY KEY, name VARCHAR(255) NOT NULL, external_code VARCHAR(255),
  region_code VARCHAR(64), use_type VARCHAR(64), fire_category VARCHAR(64) CHECK(fire_category IN ('special','other','not_applicable','unknown')),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS project_scope (
  id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(64) NOT NULL, parent_id VARCHAR(64),
  kind VARCHAR(64) NOT NULL CHECK(kind IN ('project','unit','discipline','location','contract','sample','event','drawing')),
  name VARCHAR(255) NOT NULL, attributes_json JSON NOT NULL CHECK(json_valid(attributes_json)),
  UNIQUE(id, project_id), FOREIGN KEY(parent_id, project_id) REFERENCES project_scope(id, project_id),
  FOREIGN KEY(project_id) REFERENCES project(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS project_reference_value (
  id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(64) NOT NULL, scope_id VARCHAR(64),
  bundle_id VARCHAR(64) NOT NULL, label_code VARCHAR(64) NOT NULL, raw_value LONGTEXT NOT NULL, normalized_value LONGTEXT,
  source_type VARCHAR(64) NOT NULL CHECK(source_type IN ('manifest','approved_document','review_decision')),
  source_reference LONGTEXT NOT NULL, valid_from DATETIME, valid_to DATETIME,
  FOREIGN KEY(scope_id, project_id) REFERENCES project_scope(id, project_id),
  FOREIGN KEY(bundle_id, label_code) REFERENCES label_definition(bundle_id, code),
  FOREIGN KEY(project_id) REFERENCES project(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS audit_run (
  id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(64) NOT NULL, bundle_id VARCHAR(64) NOT NULL,
  run_no BIGINT NOT NULL CHECK(run_no > 0), audit_stage VARCHAR(64) NOT NULL,
  status VARCHAR(64) NOT NULL CHECK(status IN ('pending','running','succeeded','partial','failed')),
  input_sha256 CHAR(64) NOT NULL, config_sha256 CHAR(64) NOT NULL,
  context_snapshot_json JSON NOT NULL CHECK(json_valid(context_snapshot_json)),
  coverage_snapshot_json JSON NOT NULL CHECK(json_valid(coverage_snapshot_json)),
  engine_version VARCHAR(64) NOT NULL, started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at DATETIME,
  UNIQUE(project_id, run_no), UNIQUE(id, project_id), UNIQUE(id, bundle_id),
  FOREIGN KEY(project_id) REFERENCES project(id),
  FOREIGN KEY(bundle_id) REFERENCES registry_bundle(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS source_file (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, relative_path VARCHAR(512) NOT NULL,
  original_name VARCHAR(255) NOT NULL, storage_path LONGTEXT NOT NULL, mime_type VARCHAR(255) NOT NULL,
  sha256 CHAR(64) NOT NULL, size_bytes BIGINT NOT NULL CHECK(size_bytes >= 0), physical_page_count BIGINT,
  parse_status VARCHAR(64) NOT NULL CHECK(parse_status IN ('pending','readable','partial','unreadable','unsupported')),
  parse_error_code VARCHAR(64), UNIQUE(run_id, relative_path), UNIQUE(id, run_id),
  FOREIGN KEY(run_id) REFERENCES audit_run(id),
  INDEX idx_source_file_hash (run_id, sha256)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS document_unit (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, project_id VARCHAR(64) NOT NULL, source_file_id VARCHAR(64) NOT NULL, bundle_id VARCHAR(64) NOT NULL,
  unit_no BIGINT NOT NULL CHECK(unit_no > 0), tag_code VARCHAR(64) NOT NULL,
  tag_origin VARCHAR(64) NOT NULL CHECK(tag_origin IN ('upload','title_rule','agnes','review')),
  tag_status VARCHAR(64) NOT NULL CHECK(tag_status IN ('proposed','verified','unknown','rejected')),
  identity_status VARCHAR(64) NOT NULL CHECK(identity_status IN ('target_project','other_project','unresolved')),
  scope_id VARCHAR(64), scope_status VARCHAR(64) NOT NULL CHECK(scope_status IN ('confirmed','unresolved')),
  classification_json JSON NOT NULL CHECK(json_valid(classification_json)),
  UNIQUE(source_file_id, unit_no), UNIQUE(id, source_file_id, run_id), UNIQUE(id, run_id), UNIQUE(id, run_id, bundle_id),
  FOREIGN KEY(source_file_id, run_id) REFERENCES source_file(id, run_id),
  FOREIGN KEY(run_id, bundle_id) REFERENCES audit_run(id, bundle_id),
  FOREIGN KEY(run_id, project_id) REFERENCES audit_run(id, project_id),
  FOREIGN KEY(bundle_id, tag_code) REFERENCES tag_definition(bundle_id, code),
  FOREIGN KEY(scope_id, project_id) REFERENCES project_scope(id, project_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS markdown_unit (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, source_file_id VARCHAR(64) NOT NULL, unit_no BIGINT NOT NULL CHECK(unit_no > 0),
  physical_page_no BIGINT CHECK(physical_page_no > 0), logical_locator LONGTEXT,
  source_type VARCHAR(64) NOT NULL CHECK(source_type IN ('native_pdf','native_word','native_excel','native_csv','ocr','image_ocr')),
  markdown_path LONGTEXT NOT NULL, source_map_path LONGTEXT NOT NULL, text_sha256 CHAR(64) NOT NULL,
  read_status VARCHAR(64) NOT NULL CHECK(read_status IN ('readable','partial','unreadable')),
  UNIQUE(source_file_id, unit_no), UNIQUE(id, source_file_id, run_id), UNIQUE(id, run_id),
  FOREIGN KEY(source_file_id, run_id) REFERENCES source_file(id, run_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS document_markdown (
  document_unit_id VARCHAR(64) NOT NULL, markdown_unit_id VARCHAR(64) NOT NULL, source_file_id VARCHAR(64) NOT NULL, run_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(document_unit_id, markdown_unit_id),
  FOREIGN KEY(document_unit_id, source_file_id, run_id) REFERENCES document_unit(id, source_file_id, run_id),
  FOREIGN KEY(markdown_unit_id, source_file_id, run_id) REFERENCES markdown_unit(id, source_file_id, run_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS source_fragment (
  id VARCHAR(64) PRIMARY KEY, markdown_unit_id VARCHAR(64) NOT NULL,
  fragment_no BIGINT NOT NULL CHECK(fragment_no > 0), text LONGTEXT NOT NULL,
  source VARCHAR(64) NOT NULL, bbox_json JSON CHECK(bbox_json IS NULL OR json_valid(bbox_json)),
  table_id VARCHAR(64), row_index BIGINT CHECK(row_index >= 0), column_index BIGINT CHECK(column_index >= 0),
  logical_locator LONGTEXT, UNIQUE(markdown_unit_id, fragment_no), UNIQUE(id, markdown_unit_id),
  FOREIGN KEY(markdown_unit_id) REFERENCES markdown_unit(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS evidence_span (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, markdown_unit_id VARCHAR(64) NOT NULL, fragment_id VARCHAR(64),
  quote_text LONGTEXT NOT NULL, span_start BIGINT CHECK(span_start >= 0), span_end BIGINT,
  grounding_status VARCHAR(64) NOT NULL CHECK(grounding_status IN ('verified_text','vision_transcription','unverified','rejected')),
  UNIQUE(id, markdown_unit_id), UNIQUE(id, run_id),
  CHECK(span_end IS NULL OR (span_start IS NOT NULL AND span_end >= span_start)),
  FOREIGN KEY(markdown_unit_id, run_id) REFERENCES markdown_unit(id, run_id),
  FOREIGN KEY(fragment_id, markdown_unit_id) REFERENCES source_fragment(id, markdown_unit_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS field_candidate (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, source_file_id VARCHAR(64) NOT NULL, document_unit_id VARCHAR(64) NOT NULL,
  markdown_unit_id VARCHAR(64) NOT NULL, bundle_id VARCHAR(64) NOT NULL, label_code VARCHAR(64) NOT NULL, evidence_id VARCHAR(64) NOT NULL,
  raw_value LONGTEXT NOT NULL, normalized_value LONGTEXT, value_unit VARCHAR(64), source_label LONGTEXT,
  value_role VARCHAR(64) NOT NULL CHECK(value_role IN ('subject','reference','historical','aggregate','detail','unknown')),
  source VARCHAR(64) NOT NULL CHECK(source IN ('native_rule','reference_search','agnes','review')),
  confidence DOUBLE NOT NULL CHECK(confidence >= 0 AND confidence <= 1),
  validation_status VARCHAR(64) NOT NULL CHECK(validation_status IN ('accepted','needs_review','rejected')),
  rejection_reason LONGTEXT, UNIQUE(id, document_unit_id, label_code), UNIQUE(id, run_id),
  FOREIGN KEY(document_unit_id, source_file_id, run_id) REFERENCES document_unit(id, source_file_id, run_id),
  FOREIGN KEY(markdown_unit_id, source_file_id, run_id) REFERENCES markdown_unit(id, source_file_id, run_id),
  FOREIGN KEY(document_unit_id, markdown_unit_id) REFERENCES document_markdown(document_unit_id, markdown_unit_id),
  FOREIGN KEY(document_unit_id, run_id, bundle_id) REFERENCES document_unit(id, run_id, bundle_id),
  FOREIGN KEY(bundle_id, label_code) REFERENCES label_definition(bundle_id, code),
  FOREIGN KEY(evidence_id, markdown_unit_id) REFERENCES evidence_span(id, markdown_unit_id),
  INDEX idx_candidate_lookup (run_id, label_code, validation_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS field_selection (
  document_unit_id VARCHAR(64) NOT NULL, label_code VARCHAR(64) NOT NULL, candidate_id VARCHAR(64) NOT NULL,
  purpose VARCHAR(64) NOT NULL CHECK(purpose IN ('display','identity')), rule_code VARCHAR(64) NOT NULL DEFAULT '' CHECK(rule_code=''),
  selection_reason LONGTEXT NOT NULL, PRIMARY KEY(document_unit_id, label_code, purpose, rule_code),
  FOREIGN KEY(candidate_id, document_unit_id, label_code) REFERENCES field_candidate(id, document_unit_id, label_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS rule_evaluation (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, bundle_id VARCHAR(64) NOT NULL, rule_code VARCHAR(64) NOT NULL,
  scope_key VARCHAR(128) NOT NULL, applicability VARCHAR(64) NOT NULL CHECK(applicability IN ('applicable','not_applicable','unknown')),
  result VARCHAR(64) NOT NULL CHECK(result IN ('pass','fail','needs_review','not_applicable','not_evaluated')),
  reason_code VARCHAR(255) NOT NULL, details_json JSON NOT NULL CHECK(json_valid(details_json)),
  UNIQUE(run_id, rule_code, scope_key), UNIQUE(id, run_id),
  FOREIGN KEY(run_id, bundle_id) REFERENCES audit_run(id, bundle_id),
  FOREIGN KEY(bundle_id, rule_code) REFERENCES rule_definition(bundle_id, code),
  CHECK((applicability='not_applicable' AND result='not_applicable') OR
        (applicability='unknown' AND result='not_evaluated') OR
        (applicability='applicable' AND result IN ('pass','fail','needs_review')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS rule_document (
  evaluation_id VARCHAR(64) NOT NULL, document_unit_id VARCHAR(64) NOT NULL, run_id VARCHAR(64) NOT NULL,
  relation VARCHAR(64) NOT NULL CHECK(relation IN ('accepted','rejected','similar','needs_review')),
  reason_code VARCHAR(255) NOT NULL, PRIMARY KEY(evaluation_id, document_unit_id),
  FOREIGN KEY(evaluation_id, run_id) REFERENCES rule_evaluation(id, run_id),
  FOREIGN KEY(document_unit_id, run_id) REFERENCES document_unit(id, run_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS rule_candidate (
  evaluation_id VARCHAR(64) NOT NULL, candidate_id VARCHAR(64) NOT NULL, run_id VARCHAR(64) NOT NULL,
  relation VARCHAR(64) NOT NULL CHECK(relation IN ('selected','conflicting','reference','rejected')),
  PRIMARY KEY(evaluation_id, candidate_id, relation),
  FOREIGN KEY(evaluation_id, run_id) REFERENCES rule_evaluation(id, run_id),
  FOREIGN KEY(candidate_id, run_id) REFERENCES field_candidate(id, run_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS audit_finding (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, evaluation_id VARCHAR(64),
  finding_type VARCHAR(64) NOT NULL CHECK(finding_type IN ('missing','misfiled','field_conflict','duplicate','version_conflict','unreadable','rule_gap','coverage_gap','content_gap')),
  severity VARCHAR(64) NOT NULL CHECK(severity IN ('info','warning','error')),
  status VARCHAR(64) NOT NULL CHECK(status IN ('open','resolved','disputed')),
  title LONGTEXT NOT NULL, reason_code VARCHAR(255) NOT NULL, suggestion LONGTEXT NOT NULL,
  details_json JSON NOT NULL CHECK(json_valid(details_json)), UNIQUE(id, run_id),
  FOREIGN KEY(evaluation_id, run_id) REFERENCES rule_evaluation(id, run_id),
  FOREIGN KEY(run_id) REFERENCES audit_run(id),
  INDEX idx_finding_review (run_id, status, finding_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS finding_evidence (
  finding_id VARCHAR(64) NOT NULL, evidence_id VARCHAR(64) NOT NULL, run_id VARCHAR(64) NOT NULL,
  relation VARCHAR(64) NOT NULL CHECK(relation IN ('supports','contradicts','similar')),
  PRIMARY KEY(finding_id, evidence_id, relation),
  FOREIGN KEY(finding_id, run_id) REFERENCES audit_finding(id, run_id),
  FOREIGN KEY(evidence_id, run_id) REFERENCES evidence_span(id, run_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS review_decision (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, finding_id VARCHAR(64),
  decision VARCHAR(64) NOT NULL CHECK(decision IN ('confirm','dismiss','correct','request_more')),
  reviewer_ref VARCHAR(255) NOT NULL, reason LONGTEXT NOT NULL, evidence_ids_json JSON NOT NULL CHECK(json_valid(evidence_ids_json)),
  before_json JSON NOT NULL CHECK(json_valid(before_json)), after_json JSON NOT NULL CHECK(json_valid(after_json)),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id, run_id),
  FOREIGN KEY(finding_id, run_id) REFERENCES audit_finding(id, run_id),
  FOREIGN KEY(run_id) REFERENCES audit_run(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS review_evidence (
  decision_id VARCHAR(64) NOT NULL, evidence_id VARCHAR(64) NOT NULL, run_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(decision_id, evidence_id),
  FOREIGN KEY(decision_id, run_id) REFERENCES review_decision(id, run_id),
  FOREIGN KEY(evidence_id, run_id) REFERENCES evidence_span(id, run_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS model_call (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL, purpose VARCHAR(64) NOT NULL,
  model_name VARCHAR(255) NOT NULL, prompt_sha256 CHAR(64) NOT NULL, input_sha256 CHAR(64) NOT NULL,
  status VARCHAR(64) NOT NULL CHECK(status IN ('succeeded','failed','rejected')),
  latency_ms BIGINT NOT NULL CHECK(latency_ms >= 0), usage_json JSON NOT NULL CHECK(json_valid(usage_json)),
  error_code VARCHAR(64), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(run_id) REFERENCES audit_run(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS report_artifact (
  id VARCHAR(64) PRIMARY KEY, run_id VARCHAR(64) NOT NULL,
  kind VARCHAR(64) NOT NULL CHECK(kind IN ('audit_json','audit_markdown','statement_markdown','statement_docx','evidence_index','test_report')),
  revision_no BIGINT NOT NULL CHECK(revision_no > 0), path LONGTEXT NOT NULL, sha256 CHAR(64) NOT NULL,
  validation_status VARCHAR(64) NOT NULL CHECK(validation_status IN ('pending','passed','needs_review','failed')),
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(run_id, kind, revision_no),
  FOREIGN KEY(run_id) REFERENCES audit_run(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
